@echo off
setlocal
powershell.exe -NoProfile -ExecutionPolicy Bypass -File "%~dp0tools\build-portable.ps1" %*
exit /b %ERRORLEVEL%

$script:PortableCanonicalRoot = 'C:\RepoBuild\GUCD-Aegi'

function Get-NormalizedPortablePath([string]$Path) {
    return [IO.Path]::GetFullPath($Path).TrimEnd('\')
}

function Get-PortableJunctionTarget([System.IO.FileSystemInfo]$Item) {
    $target = $Item.Target
    if ($target -is [array]) { $target = $target[0] }
    if (-not $target) { return $null }
    if (-not [IO.Path]::IsPathRooted($target)) {
        $target = Join-Path $Item.Parent.FullName $target
    }
    return Get-NormalizedPortablePath $target
}

function Ensure-PortableCanonicalRoot([string]$PhysicalRepoRoot) {
    $physicalRoot = Get-NormalizedPortablePath $PhysicalRepoRoot
    $canonicalRoot = Get-NormalizedPortablePath $script:PortableCanonicalRoot
    if (-not (Test-Path -LiteralPath $physicalRoot -PathType Container)) {
        throw "Repository root does not exist: $physicalRoot"
    }

    if ($physicalRoot -ieq $canonicalRoot) {
        return $canonicalRoot
    }

    $parent = Split-Path -Parent $canonicalRoot
    New-Item -ItemType Directory -Force -Path $parent | Out-Null

    $existing = Get-Item -LiteralPath $canonicalRoot -Force -ErrorAction SilentlyContinue
    if ($existing) {
        $isJunction = (($existing.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) -and
            ($existing.LinkType -eq 'Junction')
        if (-not $isJunction) {
            throw "$canonicalRoot already exists and is not the portable-build junction. Move or rename it, then retry."
        }

        $existingTarget = Get-PortableJunctionTarget $existing
        if ($existingTarget -ieq $physicalRoot) {
            return $canonicalRoot
        }
        if ($existingTarget -and (Test-Path -LiteralPath $existingTarget -PathType Container)) {
            throw "$canonicalRoot currently points to another existing repository: $existingTarget. Only one clone can use the canonical build path at a time."
        }

        Write-Host "Removing stale portable-build junction $canonicalRoot"
        Remove-Item -LiteralPath $canonicalRoot -Force
    }

    Write-Host "Creating portable-build junction $canonicalRoot -> $physicalRoot"
    try {
        New-Item -ItemType Junction -Path $canonicalRoot -Target $physicalRoot | Out-Null
    } catch {
        throw "Could not create the portable-build junction at $canonicalRoot. Run from an elevated PowerShell once or ensure C:\RepoBuild is writable. $($_.Exception.Message)"
    }
    return $canonicalRoot
}

function Get-PortablePhysicalRoot([string]$InvocationRoot, [string]$SuppliedPhysicalRoot) {
    if ($SuppliedPhysicalRoot) {
        return Get-NormalizedPortablePath $SuppliedPhysicalRoot
    }

    $root = Get-NormalizedPortablePath $InvocationRoot
    $canonicalRoot = Get-NormalizedPortablePath $script:PortableCanonicalRoot
    if ($root -ine $canonicalRoot) {
        return $root
    }

    $item = Get-Item -LiteralPath $canonicalRoot -Force -ErrorAction SilentlyContinue
    if ($item -and (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
        $target = Get-PortableJunctionTarget $item
        if ($target) { return $target }
    }
    return $root
}

